<?php require 'conexion.php';$m=$_SERVER['REQUEST_METHOD'];if($m==='GET'){$u=authUser($pdo);$rows=$pdo->query("SELECT i.*,u.nombre AS userName,(SELECT COUNT(*) FROM confirmaciones c WHERE c.incidente_id=i.id) AS total_confirmaciones FROM incidentes i JOIN usuarios u ON u.id=i.usuario_id ORDER BY i.creado_en DESC")->fetchAll();foreach($rows as &$r){$r['id']=$r['codigo'];$r['userId']=(int)$r['usuario_id'];$r['lat']=$r['lat']!==null?(float)$r['lat']:null;$r['lng']=$r['lng']!==null?(float)$r['lng']:null;$r['fecha']=$r['creado_en'];$r['resolved']=$r['estado']==='Resuelto';$r['confirmados']=(int)$r['total_confirmaciones'];}out(['ok'=>true,'incidentes'=>$rows]);}if($m==='POST'){$u=authUser($pdo);$d=body();$codigo='INC-'.date('YmdHis').'-'.random_int(100,999);$tipo=trim($d['tipo']??'');$desc=trim($d['descripcion']??'');$ubi=trim($d['ubicacion']??'');$lat=$d['lat']??null;$lng=$d['lng']??null;$ev=$d['evidencia']??null;if(!$tipo||!$desc||!$ubi)out(['ok'=>false,'mensaje'=>'Completa categoría, descripción y ubicación.'],422);$s=$pdo->prepare('INSERT INTO incidentes(codigo,usuario_id,tipo,descripcion,ubicacion,lat,lng,evidencia_nombre,evidencia_tipo,evidencia_datos) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->execute([$codigo,$u['id'],$tipo,$desc,$ubi,$lat,$lng,$ev['name']??null,$ev['type']??null,$ev['data']??null]);out(['ok'=>true,'codigo'=>$codigo,'mensaje'=>'Incidente registrado en MySQL correctamente.']);}if($m==='PATCH'){$u=authUser($pdo);$d=body();$codigo=$d['id']??'';$accion=$d['accion']??'';$s=$pdo->prepare('SELECT * FROM incidentes WHERE codigo=?');$s->execute([$codigo]);$i=$s->fetch();if(!$i)out(['ok'=>false,'mensaje'=>'Incidente no encontrado.'],404);if($accion==='resolver'){if((int)$i['usuario_id']!==(int)$u['id'])out(['ok'=>false,'mensaje'=>'Solo el autor puede resolver este incidente.'],403);$pdo->prepare("UPDATE incidentes SET estado='Resuelto' WHERE id=?")->execute([$i['id']]);out(['ok'=>true]);}if($accion==='confirmar'){$pdo->prepare('INSERT IGNORE INTO confirmaciones(incidente_id,usuario_id) VALUES(?,?)')->execute([$i['id'],$u['id']]);out(['ok'=>true]);}}out(['ok'=>false,'mensaje'=>'Método no permitido.'],405);
